const ops = C.ui.opinions, by = {};
ops.forEach((r) => { if (r.id) by[r.id] = r; });
const out = [];
const pick = (id, k) => { const r = by[id]; if (!r) return 'no row ' + id; r.mark(k); r.onPick(k); return 'ok'; };
for (const id of ['sh45', 'sh47', 'sh56', 'sh57', 'sh58', 'sh59']) out.push(id + ':' + (by[id] ? by[id].options.map((o) => o[0]).join('/') + ' ' + (by[id].disabled ? 'DISABLED' : '') : 'MISSING'));
out.push('sh57 o1 ' + pick('sh57', 'o1') + ' -> sol ' + C.shared.solomonVessels.current + ' lit ' + C.shared.solomonVessels.lit + ' sh45 ' + by.sh45.cur);
out.push('sh45 o0 ' + pick('sh45', 'o0') + ' -> sol ' + C.shared.solomonVessels.current + ' lit ' + C.shared.solomonVessels.lit + ' sh57 ' + by.sh57.cur);
out.push('sh47 o2 ' + pick('sh47', 'o2') + ' -> ' + C.shared.parochotCount.mode);
out.push('sh56 o2 ' + pick('sh56', 'o2') + ' -> ' + C.shared.parochetFold.mode);
out.push('sh58 o1 ' + pick('sh58', 'o1') + ' -> ' + C.shared.gateParochot.mode);
out.push('sh59 o1 ' + pick('sh59', 'o1') + ' -> ' + C.shared.aliyahParochot.mode);
for (const [id, k] of [['sh47', 'o0'], ['sh56', 'o0'], ['sh58', 'o0'], ['sh59', 'o0']]) pick(id, k);
out.push('back: ' + C.shared.parochotCount.mode + ' ' + C.shared.parochetFold.mode + ' ' + C.shared.gateParochot.mode + ' ' + C.shared.aliyahParochot.mode);
const caps = [...document.querySelectorAll('#tm-ops .tm-op .cap')].map((e) => e.textContent).filter((t) => /פרוכות|שלמה|הכהן הגדול/.test(t));
out.push('caps: ' + caps.join(' | '));
return out.join('\n');
